import{_ as e,c as i,o as l,ah as p,ao as a,ap as o}from"./chunks/framework.Dq2_gudl.js";const f=JSON.parse('{"title":"Pets in Heaven — 그들, 천국 그리고 당신의 슬픔","description":"반려동물을 떠나보낸 당신에게: 성경이 동물과 영원, 하나님의 돌보심에 대해 말하는 것. 네 편의 다정한 글.","frontmatter":{"title":"Pets in Heaven — 그들, 천국 그리고 당신의 슬픔","description":"반려동물을 떠나보낸 당신에게: 성경이 동물과 영원, 하나님의 돌보심에 대해 말하는 것. 네 편의 다정한 글."},"headers":[],"relativePath":"ko/pets-in-heaven/index.md","filePath":"ko/pets-in-heaven/index.md"}'),t={name:"ko/pets-in-heaven/index.md"};function n(c,s,r,d,v,h){return l(),i("div",null,[...s[0]||(s[0]=[p('<div class="pl-quote"><p>「그 아이가 떠난 뒤, 제가 정말 알고 싶었던 건 하나였어요. 지금 잘 지내고 있을까요? 우리 다시 만날 수 있을까요?」</p><p class="pl-quote-soft">성경은 모든 질문에 한 문장으로 답하지 않습니다. 하지만 가장 어두운 밤에도 소망을 볼 수 있을 만큼의 빛은 주십니다.</p></div><section class="pl-section"><h2>시작하기 전에</h2><p class="pl-lead">여기는 당신에게 「빨리 털어내라」고 요구하는 곳이 아닙니다. 이 네 편의 글은 아직 그리운 당신을 위한 것입니다.</p><p>동물 친구를 잃는 것은 참 특별한 슬픔입니다. 사람들은 「그냥 개 한 마리였잖아」, 「다른 아이를 키워」라고 말합니다. 하지만 당신은 그게 사실이 아니라는 걸 압니다. 그 아이는 당신의 발소리를 알아들었고, 당신의 가장 힘들었던 한 해 동안 발치에 붙어 있었습니다. 그 아이와 함께 사라진 것은 매일 아침 당신을 가장 먼저 맞아주던 눈빛이었습니다.</p><p>성경은 사실 동물에 대해 많은 말을 합니다. 하나님은 동물을 창조하시고, 먹이시고, 그들과 언약을 세우시고, 새롭게 하실 세상 안에 그들을 두셨습니다. 이 구절들이 「모든 반려동물은 천국에 있다」는 것을 증명하지는 않습니다. 성경은 그렇게 약속하지 않습니다. 하지만 다정한 사실 하나를 보여줍니다. <strong>하나님의 계획 안에서 동물은 버려도 되는 조연이 아니었습니다.</strong></p><p>여기서 읽게 되는 것이 구절에 그치지 않기를 바랍니다. 참새 한 마리까지 기억하시는 그 하나님이 당신의 아이도 기억하신다는 것을 느끼시기를 바랍니다.</p></section><section class="pl-section"><h2>당신을 위한 네 편의 글</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/ko/pets-in-heaven/will-i-see-my-pet-again">다시 만날 수 있을까요?</a></h3><p>동물과 천국에 대한 성경의 소망 — 피조물도 함께 구원을 기다리며, 새 창조에도 동물이 있습니다.</p><p class="pl-quote-soft">로마서 8:19-22 · 이사야 11:6-9 · 요한계시록 21:4-5</p></div><div class="pl-new-card"><h3><a href="/ko/pets-in-heaven/not-one-sparrow-forgotten">참새 한 마리도 잊히지 않습니다</a></h3><p>그 아이는 너무 작았습니다. 세상이 기억할까요? 예수님은 참새 한 마리 떨어져도 하늘 아버지가 아신다고 하셨습니다.</p><p class="pl-quote-soft">마태복음 10:29-31 · 시편 147:9 · 시편 36:6</p></div><div class="pl-new-card"><h3><a href="/ko/pets-in-heaven/rainbow-bridge-covenant">무지개 다리 건너편</a></h3><p>「무지개 다리」는 아름다운 표현이고, 성경에도 정말 무지개가 있습니다. 하나님께서 <em>모든 생물</em>과 세우신 영원한 언약입니다.</p><p class="pl-quote-soft">창세기 9:9-13 · 이사야 65:25 · 요한계시록 5:13</p></div><div class="pl-new-card"><h3><a href="/ko/pets-in-heaven/permission-to-grieve">슬퍼해도 괜찮습니다</a></h3><p>하나님은 당신의 눈물을 병에 담아 두십니다. 슬픔은 믿음이 부족한 게 아니라, 사랑이 계속되는 것입니다.</p><p class="pl-quote-soft">시편 56:8 · 시편 34:18 · 마태복음 5:4</p></div></div></section><section class="pl-section"><h2>읽는 방법</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>천천히, 한 번에 다 읽지 말고</h3><p>한 단락이면 충분합니다. 어떤 구절에서 갑자기 눈물이 난다면 거기서 멈추세요. 약함이 아니라 사랑이 흐르는 것입니다.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>구절에 그 아이 이름을 넣어 보세요</h3><p>「하나님이 짐승에게 먹이를 주신다」를 읽을 때, 마음속으로 그 이름을 넣어 보세요. 하나님은 그 아이도 그렇게 돌보셨습니다.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>읽고 나서 한 마디 해 주세요</h3><p>예쁘게 쓸 필요 없습니다. 「많이 보고 싶어」면 충분합니다. 더 쓰고 싶다면 PetLoss의 안내 일기가 곁에 있겠습니다.</p></div></div></section><section class="pl-section"><h2>모든 구절 한눈에 보기</h2><p class="pl-lead">이 네 편의 글에 나오는 모든 구절을 여기에 모았습니다. 다시 읽고 천천히 찾아보세요.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/ko/pets-in-heaven/will-i-see-my-pet-again">다시 만날 수 있을까요?</a></h3><ul class="pl-verse-list"><li>로마서 8:19-22</li><li>이사야 11:6-9</li><li>요한계시록 21:4-5</li><li>시편 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ko/pets-in-heaven/not-one-sparrow-forgotten">참새 한 마리도 잊히지 않습니다</a></h3><ul class="pl-verse-list"><li>마태복음 10:29-31</li><li>시편 147:9</li><li>시편 36:6</li><li>시편 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/ko/pets-in-heaven/rainbow-bridge-covenant">무지개 다리 건너편</a></h3><ul class="pl-verse-list"><li>창세기 9:9-13</li><li>이사야 65:25</li><li>요한계시록 5:13</li><li>시편 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ko/pets-in-heaven/permission-to-grieve">슬퍼해도 괜찮습니다</a></h3><ul class="pl-verse-list"><li>시편 56:8</li><li>시편 34:18</li><li>시편 147:3</li><li>마태복음 5:4</li><li>요한복음 11:35</li><li>요한계시록 21:4</li></ul></div></div></section><div class="pl-cta"><h2>이곳에서 조용히 안아지기를 바랍니다.</h2><p>그 아이의 사진을 두고 미처 못 한 말을 쓰고 싶다면, PetLoss가 조용히 곁에 있겠습니다. 계정도, 업로드도 없이 완전히 오프라인으로.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store에서 다운로드</a><p class="pl-disclaimer">이 글들은 신앙적 묵상과 정서적 동반을 제공하며, 의료·심리·치료 상담이 아닙니다. 슬픔이 오래 일상을 막는다면 면허 있는 전문가나 지역 지원 핫라인에 도움을 청하세요. 성경 인용은 흠정역(KJV)입니다.</p></div><div class="pl-bible"><h3>말씀이 계속 곁에 있도록</h3><p>이 네 편의 글에 나오는 모든 구절은 성경에서 왔습니다. 무지개 성경 위젯 앱으로 언제든 말씀을 읽고 매일 말씀 위젯을 설정해 보세요. 그리운 날들에 작은 등불이 되어 줄 것입니다.</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 홈 화면 위젯 — 2 Timothy 2:13" loading="lazy"><figcaption>매일 말씀을 홈 화면에</figcaption></figure><figure><img src="'+o+'" alt="Rainbow Bible — 하늘나라의 반려동물 주제, 마태복음 10:29-31" loading="lazy"><figcaption>「하늘나라의 반려동물」 주제로 전환해 읽기</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Store에서 무지개 성경 위젯 받기</a></div>',7)])])}const g=e(t,[["render",n]]);export{f as __pageData,g as default};
